let objChart={},datasets;(function(){function t(t){var i=[];n.find("input:checked").each(function(){var n=$(this).attr("name");n&&datasets[n]&&i.push(datasets[n])});i.length>0&&$.plot($("#placeholder"),i,{yaxis:{min:t},xaxis:{tickDecimals:0}})}var n;$(document).ready(function(){n=$("#choices")});objChart.InitData=function(){datasets={Open:{label:"History",data:[]}}};objChart.SetChart=function(i){var r=0;$.each(datasets,function(n,t){t.color=r;++r});n.empty();$.each(datasets,function(t,i){n.append('<input type="checkbox" name="'+t+'" checked="checked" id="id'+t+'" style="display:none;"><label for="id'+t+'" style="display:none;">'+i.label+"<\/label>")});setTimeout(function(){t(i)},1e3)}})(objChart);